import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const MESSAGE_TYPES = ['NOTE', 'CHAT', 'MAIL'];
// 가정: 연계 전달 성공 여부는 DB 기록이 끝나면 SUCCESS로 계산한다.
const DELIVERY_SUCCESS = 'SUCCESS';
// 가정: linkStatus는 수신자 행이 모두 만들어지면 LINKED로 정한다.
const LINK_LINKED = 'LINKED';

@Controller('api/v1')
export class FnSfr00109Controller {
  @Post('/messages')
  @HttpCode(200)
  async createMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body) as Record<string, unknown>;

    const messageType = data['messageType'];
    if (typeof messageType !== 'string' || !MESSAGE_TYPES.includes(messageType)) {
      throw new ApiError(422, 'MESSAGE_INPUT_MISSING', '전달 수단을 선택해 주세요.');
    }
    const rawIds = data['recipientIds'];
    if (!Array.isArray(rawIds) || rawIds.length === 0) {
      throw new ApiError(422, 'MESSAGE_INPUT_MISSING', '수신자를 지정해 주세요.');
    }
    const recipientIds: number[] = [];
    for (const raw of rawIds) {
      const n = Number(raw);
      if (raw === null || raw === '' || !Number.isInteger(n) || n <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '수신자 ID 형식이 올바르지 않습니다.');
      }
      if (!recipientIds.includes(n)) {
        recipientIds.push(n);
      }
    }

    const targetType = data['targetType'];
    if (typeof targetType !== 'string' || targetType.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '연계 대상 업무 항목 유형을 입력해 주세요.');
    }
    const targetId = data['targetId'];
    if (typeof targetId !== 'number' || !Number.isInteger(targetId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연계 대상 업무 항목 ID는 정수여야 합니다.');
    }

    const subject = data['subject'];
    if (subject !== undefined && subject !== null && (typeof subject !== 'string' || subject.length > 300)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '제목은 300자 이내의 글자여야 합니다.');
    }
    const content = data['content'];
    if (content !== undefined && content !== null && typeof content !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '내용 형식이 올바르지 않습니다.');
    }
    const attachmentRef = data['attachmentRef'];
    if (attachmentRef !== undefined && attachmentRef !== null && (typeof attachmentRef !== 'string' || attachmentRef.length > 200)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '첨부파일 연결은 200자 이내의 글자여야 합니다.');
    }
    // 가정: 메시지 내용 또는 첨부파일 중 하나 이상 필요.
    const hasContent = typeof content === 'string' && content.trim() !== '';
    const hasAttachment = typeof attachmentRef === 'string' && attachmentRef.trim() !== '';
    if (!hasContent && !hasAttachment) {
      throw new ApiError(400, 'VALIDATION_FAILED', '내용 또는 첨부파일 중 하나 이상 입력해 주세요.');
    }

    return transaction(async (db) => {
      // 가정: 전달 대상 권한은 사용 중인 메뉴 사용 권한이 하나 이상 있는 임직원에게 허용한다.
      const perm = await db.query(
        "SELECT COUNT(*) AS \"cnt\" FROM menu_permission WHERE employee_id = CAST(:userId AS bigint) AND use_yn = '사용'",
        { userId: user.id },
      );
      if (!perm[0] || Number(perm[0]['cnt']) === 0) {
        throw new ApiError(409, 'MESSAGE_TARGET_FORBIDDEN', '전달 대상 업무 항목에 대한 권한이 없습니다.');
      }

      for (const rid of recipientIds) {
        const found = await db.query(
          'SELECT COUNT(*) AS \"cnt\" FROM employee WHERE employee_id = CAST(:rid AS bigint)',
          { rid: String(rid) },
        );
        if (!found[0] || Number(found[0]['cnt']) === 0) {
          throw new ApiError(404, 'NOT_FOUND', '수신 임직원을 찾을 수 없습니다.');
        }
      }

      const inserted = await db.query(
        'INSERT INTO message (sender_id, message_type, subject, content, attachment_ref, sent_at, created_at, updated_at) ' +
          'VALUES (CAST(:userId AS bigint), :messageType, :subject, :content, :attachmentRef, now(), now(), now()) ' +
          'RETURNING message_id AS \"messageId\"',
        {
          userId: user.id,
          messageType,
          subject: subject ?? null,
          content: content ?? null,
          attachmentRef: attachmentRef ?? null,
        },
      );
      const messageId = Number(inserted[0]['messageId']);

      let linked = 0;
      for (const rid of recipientIds) {
        linked += await db.execute(
          'INSERT INTO message_recipient (message_id, recipient_id, created_at, updated_at) ' +
            'VALUES (CAST(:messageId AS bigint), CAST(:rid AS bigint), now(), now())',
          { messageId: String(messageId), rid: String(rid) },
        );
      }

      return {
        messageId,
        deliveryResult: DELIVERY_SUCCESS,
        linkStatus: linked === recipientIds.length ? LINK_LINKED : 'PARTIAL',
      };
    });
  }
}

