import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  NumberInput,
  RefName,
  Select,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['MAIL', '전자우편'],
  ['CHAT', '메신저'],
  ['NOTE', '쪽지'],
];

const TYPE_NAMES: Record<string, string> = { MAIL: '전자우편', CHAT: '메신저', NOTE: '쪽지' };

export default function FnSfr00109Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [messageType, setMessageType] = useState('');
  const [subject, setSubject] = useState('');
  const [content, setContent] = useState('');
  const [attachmentRef, setAttachmentRef] = useState('');
  const [recipientIds, setRecipientIds] = useState<number[]>([]);
  const [picked, setPicked] = useState<number | string>('');
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');

  function reset() {
    setMessageType('');
    setSubject('');
    setContent('');
    setAttachmentRef('');
    setRecipientIds([]);
    setPicked('');
    setTargetType('');
    setTargetId('');
  }

  function addRecipient() {
    const id = Number(picked);
    if (picked === '' || !Number.isInteger(id)) {
      return;
    }
    if (!recipientIds.includes(id)) {
      setRecipientIds([...recipientIds, id]);
    }
    setPicked('');
  }

  async function send() {
    if (messageType === '') {
      throw new Error('전달 수단을 선택해 주세요.');
    }
    if (recipientIds.length === 0) {
      throw new Error('수신자를 지정해 주세요.');
    }
    if (targetType.trim() === '' || targetId === '') {
      throw new Error('연계 대상 업무 항목 유형과 ID를 입력해 주세요.');
    }
    if (content.trim() === '' && attachmentRef.trim() === '') {
      throw new Error('내용 또는 첨부파일 중 하나 이상 입력해 주세요.');
    }
    const body: Row = {
      messageType,
      subject,
      content,
      attachmentRef,
      recipientIds,
      targetType: targetType.trim(),
      targetId: Number(targetId),
    };
    const res = await call<Row>('POST', '/messages', role, body);
    setResults([
      {
        messageId: res.messageId,
        messageType,
        subject,
        recipientIds,
        targetType: targetType.trim(),
        targetId: Number(targetId),
        deliveryResult: res.deliveryResult,
        linkStatus: res.linkStatus,
      },
      ...results,
    ]);
    notify('전달했습니다.');
    reset();
    setOpen(false);
  }

  const successCount = results.filter((r) => r.deliveryResult === 'SUCCESS').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>전달 현황</h2>
        <Tiles
          items={[
            ['이번 화면 전달 건수', results.length],
            ['전달 성공', successCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>전달 내역</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => setOpen(true)}>
            전자우편·메신저 전달
          </button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 전달한 내역이 없습니다."
          columns={[
            { key: 'messageId', label: '메시지 ID' },
            {
              key: 'messageType',
              label: '전달 수단',
              render: (r) => TYPE_NAMES[String(r.messageType)] ?? String(r.messageType),
            },
            { key: 'subject', label: '제목' },
            {
              key: 'recipientIds',
              label: '수신 임직원',
              render: (r) => (
                <span>
                  {(r.recipientIds as number[]).map((id) => (
                    <span key={id}>
                      <RefName table="employee" role={role} value={id} />{' '}
                    </span>
                  ))}
                </span>
              ),
            },
            { key: 'targetType', label: '연계 대상 업무 항목 유형' },
            { key: 'targetId', label: '연계 대상 업무 항목 ID' },
            { key: 'deliveryResult', label: '전달 성공·실패 여부', render: (r) => <Badge value={r.deliveryResult} /> },
            { key: 'linkStatus', label: '업무 항목과 전달 이력의 연결 결과', render: (r) => <Badge value={r.linkStatus} /> },
          ]}
        />
      </section>
      {open && (
        <Drawer
          title="전자우편·메신저 전달"
          onClose={() => {
            setOpen(false);
          }}
        >
          <Form onSubmit={send} submit="전달">
            <Field label="전달 수단(전자우편 MAIL / 메신저 CHAT)" required>
              <Select value={messageType} onChange={setMessageType} options={TYPE_OPTIONS} />
            </Field>
            <Field label="수신 임직원 ID 목록" required wide hint="임직원을 고른 뒤 추가를 누르세요.">
              <LookupSelect table="employee" role={role} value={picked} onChange={setPicked} />
              <button type="button" onClick={addRecipient}>
                추가
              </button>
              <div>
                {recipientIds.map((id) => (
                  <span key={id}>
                    <RefName table="employee" role={role} value={id} />{' '}
                    <button type="button" onClick={() => setRecipientIds(recipientIds.filter((x) => x !== id))}>
                      삭제
                    </button>{' '}
                  </span>
                ))}
              </div>
            </Field>
            <Field label="연계 대상 업무 항목 유형" required>
              <TextInput value={targetType} onChange={setTargetType} />
            </Field>
            <Field label="연계 대상 업무 항목 ID" required>
              <NumberInput value={targetId} onChange={setTargetId} />
            </Field>
            <Field label="제목" wide>
              <TextInput value={subject} onChange={setSubject} />
            </Field>
            <Field label="공유할 업무 항목 내용" wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label="첨부파일 연결" wide>
              <TextInput value={attachmentRef} onChange={setAttachmentRef} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
